<?php
declare(strict_types=1);
putenv('RUMOHUB_ENABLED=0');require dirname(__DIR__).'/app/bootstrap.php';$checks=0;
function check(bool $value,string $label):void{global $checks;$checks++;if(!$value)throw new RuntimeException($label);}
function rejects(callable $f,string $label):void{try{$f();}catch(InvalidArgumentException|RuntimeException $e){check(true,$label);return;}check(false,$label);}
$c=Competition::catalog();$pin=CompetitionReference::pin($c['br-a'],'2026-sim-v07');check(CompetitionReference::verify($pin),'snapshot íntegro');$changed=$pin;$changed['definition']['rules']['access']=999;check(!CompetitionReference::verify($changed),'alteração detectada');$copy=$c['br-a'];$copy['name']='Outra edição';check($pin['definition']['name']!==$copy['name'],'snapshot independente');rejects(fn()=>CompetitionReference::pin($c['br-a'],'2026','official_dated'),'fonte primária obrigatória');
$defs=['a'=>['country'=>'BR','scope'=>'state','pyramid'=>'BR-SP','teams'=>['A','B']],'b'=>['country'=>'BR','scope'=>'state','pyramid'=>'BR-SP','teams'=>['C','D']],'cup'=>['country'=>'BR','scope'=>'national','teams'=>['A','C']]];
$link=['from'=>'b','to'=>'a','kind'=>'promotion','slots'=>1,'verified_sources'=>['fixture_source']];check(CompetitionReference::graph($defs,[$link])===[],'vínculo validado');check(in_array('promotion_cycle',array_column(CompetitionReference::graph($defs,[$link,array_replace($link,['from'=>'a','to'=>'b'])]),'code')),'ciclo detectado');check(in_array('different_pyramid',array_column(CompetitionReference::graph($defs,[array_replace($link,['to'=>'cup'])]),'code')),'estadual não promove nacional');check(CompetitionReference::graph($defs,[array_replace($link,['to'=>'cup','kind'=>'qualification'])])===[],'classificação não é promoção');
$t=['liga'=>['id'=>'liga','matches'=>array_map(fn($r)=>['round'=>$r,'home'=>'A','away'=>'B'],range(1,8))],'copa'=>['id'=>'copa','matches'=>[['round'=>1,'home'=>'A','away'=>'C'],['round'=>2,'home'=>'D','away'=>'A']]]];
$evidence=[];for($season=1;$season<=5;$season++){$start=hrtime(true);$agenda=CompetitionCalendar::build(999,$season,$t,(2025+$season).'-01-01');$busy=[];foreach($agenda as $m){check($m['date_basis']==='simulation_adaptation','rotulagem');foreach(['home','away'] as $side){$club=$m[$side];$day=strtotime($m['date'].' UTC');if(isset($busy[$club]))check($day-$busy[$club]>=3*86400,'descanso compartilhado');$busy[$club]=$day;}}check(count($agenda)===10,'partidas sem duplicar');check($agenda===CompetitionCalendar::build(999,$season,$t,(2025+$season).'-01-01',3,$agenda),'replay idempotente');$evidence[]=['season'=>$season,'matches'=>count($agenda),'elapsed_ms'=>round((hrtime(true)-$start)/1e6,3),'bytes'=>strlen(json_encode($agenda)),'first'=>$agenda[0]['date'],'last'=>end($agenda)['date']];}
$base=CompetitionCalendar::build(999,1,['liga'=>$t['liga']],'2026-01-01');$extended=CompetitionCalendar::build(999,1,$t,'2026-01-01',3,$base);$by=array_column($extended,null,'key');foreach($base as $entry)check($by[$entry['key']]===$entry,'nova competição preserva datas existentes');
$bad=$base;$bad[0]['home']='invasor';rejects(fn()=>CompetitionCalendar::build(999,1,['liga'=>$t['liga']],'2026-01-01',3,$bad),'autoria não pode mudar');$dup=$t;$dup['liga']['matches'][]=$dup['liga']['matches'][0];rejects(fn()=>CompetitionCalendar::build(999,1,$dup,'2026-01-01'),'jogo duplicado');rejects(fn()=>CompetitionCalendar::build(999,1,$t,'2026-02-31'),'data inválida');check(CompetitionCalendar::build(1000,1,$t,'2026-01-01')[0]['key']!==CompetitionCalendar::build(999,1,$t,'2026-01-01')[0]['key'],'saves isolados');
$europe=CompetitionCalendar::build(999,1,$t,'2026-07-01');check($europe[0]['date']==='2026-07-01','janela sul/norte parametrizada, não calendário oficial');$long=['liga'=>['id'=>'liga','matches'=>array_map(fn($r)=>['round'=>$r,'home'=>'A','away'=>'B'],range(1,150))]];rejects(fn()=>CompetitionCalendar::build(999,1,$long,'2026-01-01'),'não estoura janela anual silenciosamente');
$out=dirname(__DIR__).'/Docs/mundializacao-v07';if(!is_dir($out))mkdir($out,0770,true);file_put_contents($out.'/foundation-tests.json',json_encode(['checks'=>$checks,'calendar_only_not_gameplay_simulation'=>true,'five_calendar_seasons'=>$evidence],JSON_PRETTY_PRINT));echo "OK: $checks verificações de referência/agenda; cinco agendas, não cinco carreiras completas.\n";
